int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int x : nums) count.merge(x, 1, Integer::sum);
    List<Integer> values = new ArrayList<>(count.keySet());
    values.sort((a, b) -> Integer.compare(count.get(b), count.get(a)));   // most frequent first
    int[] out = new int[k];
    for (int i = 0; i < k; i++) out[i] = values.get(i);
    return out;
}

vector<int> topKFrequent(vector<int>& nums, int k) {
    unordered_map<int, int> count;
    for (int x : nums) count[x]++;
    vector<pair<int, int>> byCount;                    // (count, value)
    for (auto& [value, c] : count) byCount.push_back({c, value});
    sort(byCount.rbegin(), byCount.rend());            // most frequent first
    vector<int> out;
    for (int i = 0; i < k; i++) out.push_back(byCount[i].second);
    return out;
}

