import heapq
from collections import Counter

def top_k_frequent(nums, k):
    heap = []                                   # (count, value): the least frequent on top
    for value, c in Counter(nums).items():
        heapq.heappush(heap, (c, value))
        if len(heap) > k:
            heapq.heappop(heap)                 # drop the least frequent: not in the top k
    return [value for _, value in heap]

int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int x : nums) count.merge(x, 1, Integer::sum);
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[1], b[1]));   // {value, count}
    for (Map.Entry<Integer, Integer> e : count.entrySet()) {
        heap.offer(new int[]{e.getKey(), e.getValue()});
        if (heap.size() > k) heap.poll();       // drop the least frequent: not in the top k
    }
    int[] out = new int[k];
    for (int i = 0; i < k; i++) out[i] = heap.poll()[0];
    return out;
}

vector<int> topKFrequent(vector<int>& nums, int k) {
    unordered_map<int, int> count;
    for (int x : nums) count[x]++;
    // (count, value) with greater<>: a min-heap, the least frequent on top
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> heap;
    for (auto& [value, c] : count) {
        heap.push({c, value});
        if ((int)heap.size() > k) heap.pop();   // drop the least frequent: not in the top k
    }
    vector<int> out;
    while (!heap.empty()) {
        out.push_back(heap.top().second);
        heap.pop();
    }
    return out;
}

function topKFrequent(nums, k) {
  const count = new Map();
  for (const x of nums) count.set(x, (count.get(x) ?? 0) + 1);
  const buckets = Array.from({ length: nums.length + 1 }, () => []);   // buckets[c] = values seen c times
  for (const [value, c] of count) buckets[c].push(value);
  const out = [];
  for (let c = nums.length; c > 0 && out.length < k; c--) out.push(...buckets[c]);   // most frequent first
  return out.slice(0, k);
}

int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int x : nums) count.merge(x, 1, Integer::sum);
    List<List<Integer>> buckets = new ArrayList<>();       // buckets.get(c) = values seen c times
    for (int c = 0; c <= nums.length; c++) buckets.add(new ArrayList<>());
    for (Map.Entry<Integer, Integer> e : count.entrySet()) buckets.get(e.getValue()).add(e.getKey());
    int[] out = new int[k];
    int filled = 0;
    for (int c = nums.length; c > 0 && filled < k; c--)    // most frequent first
        for (int value : buckets.get(c)) if (filled < k) out[filled++] = value;
    return out;
}

vector<int> topKFrequent(vector<int>& nums, int k) {
    unordered_map<int, int> count;
    for (int x : nums) count[x]++;
    vector<vector<int>> buckets(nums.size() + 1);         // buckets[c] = values seen c times
    for (auto& [value, c] : count) buckets[c].push_back(value);
    vector<int> out;
    for (int c = nums.size(); c > 0 && (int)out.size() < k; c--)   // most frequent first
        for (int value : buckets[c]) if ((int)out.size() < k) out.push_back(value);
    return out;
}
